23	/**
24	 * Represents a validated and ready-to-execute tool call.
25	 * An instance of this is created by a `ToolBuilder`.
26	 */
27	export interface ToolInvocation<
28	  TParams extends object,
29	  TResult extends ToolResult,
30	> {
31	  /**
32	   * The validated parameters for this specific invocation.
33	   */
34	  params: TParams;
35	
36	  /**
37	   * Gets a pre-execution description of the tool operation.
38	   *
39	   * @returns A markdown string describing what the tool will do.
40	   */
41	  getDescription(): string;
42	
43	  /**
44	   * Determines what file system paths the tool will affect.
45	   * @returns A list of such paths.
46	   */
47	  toolLocations(): ToolLocation[];
48	
49	  /**
50	   * Checks if the tool call should be confirmed by the user before execution.
51	   *
52	   * @param abortSignal An AbortSignal that can be used to cancel the confirmation request.
53	   * @returns A ToolCallConfirmationDetails object if confirmation is required, or false if not.
54	   */
55	  shouldConfirmExecute(
56	    abortSignal: AbortSignal,
57	  ): Promise<ToolCallConfirmationDetails | false>;
58	
59	  /**
60	   * Executes the tool with the validated parameters.
61	   * @param signal AbortSignal for tool cancellation.
62	   * @param updateOutput Optional callback to stream output.
63	   * @returns Result of the tool execution.
64	   */
65	  execute(
66	    signal: AbortSignal,
67	    updateOutput?: (output: string | AnsiOutput) => void,
68	    shellExecutionConfig?: ShellExecutionConfig,
69	  ): Promise<TResult>;
70	}
71	
72	/**
73	 * Options for policy updates that can be customized by tool invocations.
74	 */
75	export interface PolicyUpdateOptions {
76	  commandPrefix?: string | string[];
77	  mcpName?: string;
78	}
79	
80	/**
81	 * A convenience base class for ToolInvocation.
82	 */
83	export abstract class BaseToolInvocation<
84	  TParams extends object,
85	  TResult extends ToolResult,
86	> implements ToolInvocation<TParams, TResult>
87	{
88	  constructor(
89	    readonly params: TParams,
90	    protected readonly messageBus: MessageBus,
91	    readonly _toolName?: string,
92	    readonly _toolDisplayName?: string,
93	    readonly _serverName?: string,
94	  ) {}
95	
96	  abstract getDescription(): string;
97	
98	  toolLocations(): ToolLocation[] {
99	    return [];
100	  }
101	
102	  async shouldConfirmExecute(
103	    abortSignal: AbortSignal,
104	  ): Promise<ToolCallConfirmationDetails | false> {
105	    const decision = await this.getMessageBusDecision(abortSignal);
106	    if (decision === 'ALLOW') {
107	      return false;
108	    }
109	
110	    if (decision === 'DENY') {
111	      throw new Error(
112	        `Tool execution for "${
113	          this._toolDisplayName || this._toolName
114	        }" denied by policy.`,
115	      );
116	    }
117	
118	    if (decision === 'ASK_USER') {
119	      return this.getConfirmationDetails(abortSignal);
120	    }
121	
122	    // Default to confirmation details if decision is unknown (should not happen with exhaustive policy)
123	    return this.getConfirmationDetails(abortSignal);
124	  }
125	
126	  /**
127	   * Returns tool-specific options for policy updates.
128	   * Subclasses can override this to provide additional options like
129	   * commandPrefix (for shell) or mcpName (for MCP tools).
130	   */
131	  protected getPolicyUpdateOptions(
132	    _outcome: ToolConfirmationOutcome,
133	  ): PolicyUpdateOptions | undefined {
134	    return undefined;
135	  }
136	
137	  /**
138	   * Helper method to publish a policy update when user selects
139	   * ProceedAlways or ProceedAlwaysAndSave.
140	   */
141	  protected async publishPolicyUpdate(
142	    outcome: ToolConfirmationOutcome,
143	  ): Promise<void> {
144	    if (
145	      outcome === ToolConfirmationOutcome.ProceedAlways ||
146	      outcome === ToolConfirmationOutcome.ProceedAlwaysAndSave
147	    ) {
148	      if (this._toolName) {
149	        const options = this.getPolicyUpdateOptions(outcome);
150	        void this.messageBus.publish({
151	          type: MessageBusType.UPDATE_POLICY,
152	          toolName: this._toolName,
153	          persist: outcome === ToolConfirmationOutcome.ProceedAlwaysAndSave,
154	          ...options,
155	        });
156	      }
157	    }
158	  }
159	
160	  /**
161	   * Subclasses should override this method to provide custom confirmation UI
162	   * when the policy engine's decision is 'ASK_USER'.
163	   * The base implementation provides a generic confirmation prompt.
164	   */
165	  protected async getConfirmationDetails(
166	    _abortSignal: AbortSignal,
167	  ): Promise<ToolCallConfirmationDetails | false> {
168	    if (!this.messageBus) {
169	      return false;
170	    }
171	
172	    const confirmationDetails: ToolCallConfirmationDetails = {
173	      type: 'info',
174	      title: `Confirm: ${this._toolDisplayName || this._toolName}`,
175	      prompt: this.getDescription(),
176	      onConfirm: async (_outcome: ToolConfirmationOutcome) => {
177	        // Policy updates are now handled centrally by the scheduler
178	      },
179	    };
180	    return confirmationDetails;
181	  }
182	
183	  protected getMessageBusDecision(
184	    abortSignal: AbortSignal,
185	  ): Promise<'ALLOW' | 'DENY' | 'ASK_USER'> {
186	    if (!this.messageBus || !this._toolName) {
187	      // If there's no message bus, we can't make a decision, so we allow.
188	      // The legacy confirmation flow will still apply if the tool needs it.
189	      return Promise.resolve('ALLOW');
190	    }
191	
192	    const correlationId = randomUUID();
193	    const request: ToolConfirmationRequest = {
194	      type: MessageBusType.TOOL_CONFIRMATION_REQUEST,
195	      correlationId,
196	      toolCall: {
197	        name: this._toolName,
198	        // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
199	        args: this.params as Record<string, unknown>,
200	      },
201	      serverName: this._serverName,
202	    };
203	
204	    return new Promise<'ALLOW' | 'DENY' | 'ASK_USER'>((resolve) => {
205	      if (!this.messageBus) {
206	        resolve('ALLOW');
207	        return;
208	      }
209	
210	      let timeoutId: NodeJS.Timeout | null = null;
211	      let unsubscribe: (() => void) | null = null;
212	
213	      const cleanup = () => {
214	        if (timeoutId) {
215	          clearTimeout(timeoutId);
216	          timeoutId = null;
217	        }
218	        if (unsubscribe) {
219	          unsubscribe();
220	          unsubscribe = null;
221	        }
222	        abortSignal.removeEventListener('abort', abortHandler);
223	      };
224	
225	      const abortHandler = () => {
226	        cleanup();
227	        resolve('DENY');
228	      };
229	
230	      if (abortSignal.aborted) {
231	        resolve('DENY');
232	        return;
233	      }
234	
235	      const responseHandler = (response: ToolConfirmationResponse) => {
236	        if (response.correlationId === correlationId) {
237	          cleanup();
238	          if (response.requiresUserConfirmation) {
239	            resolve('ASK_USER');
240	          } else if (response.confirmed) {
