122	    const confirmationDetails: ToolMcpConfirmationDetails = {
123	      type: 'mcp',
124	      title: 'Confirm MCP Tool Execution',
125	      serverName: this.serverName,
126	      toolName: this.serverToolName, // Display original tool name in confirmation
127	      toolDisplayName: this.displayName, // Display global registry name exposed to model and user
128	      toolArgs: this.params,
129	      toolDescription: this.toolDescription,
130	      toolParameterSchema: this.toolParameterSchema,
131	      onConfirm: async (outcome: ToolConfirmationOutcome) => {
132	        if (outcome === ToolConfirmationOutcome.ProceedAlwaysServer) {
133	          DiscoveredMCPToolInvocation.allowlist.add(serverAllowListKey);
134	        } else if (outcome === ToolConfirmationOutcome.ProceedAlwaysTool) {
135	          DiscoveredMCPToolInvocation.allowlist.add(toolAllowListKey);
136	        } else if (outcome === ToolConfirmationOutcome.ProceedAlwaysAndSave) {
137	          DiscoveredMCPToolInvocation.allowlist.add(toolAllowListKey);
