117	      const displayContent = `
118	Subagent ${this.definition.name} Finished
119	
120	Termination Reason:\n ${output.terminate_reason}
121	
122	Result:
123	${output.result}
124	`;
125	
126	      return {
127	        llmContent: [{ text: resultContent }],
128	        returnDisplay: displayContent,
129	      };
130	    } catch (error) {
131	      const errorMessage =
132	        error instanceof Error ? error.message : String(error);
