54	  override get isReadOnly(): boolean {
55	    if (this._memoizedIsReadOnly !== undefined) {
56	      return this._memoizedIsReadOnly;
57	    }
58	    // No try-catch here. If getToolRegistry() throws, we let it throw.
59	    // This is an invariant: you can't check read-only status if the system isn't initialized.
60	    this._memoizedIsReadOnly = SubagentTool.checkIsReadOnly(
