export const BROWSER_MCP_SERVER_NAME = 'browser-agent';

type ToolParams = Record<string, unknown>;

/**
 * Extracts the concatenated text from a set of MCP content items.
 */
function extractTextContent(content: McpContentItem[] | undefined): string {
  if (!content || content.length === 0) {
    return '';
  }
  return content
    .filter((item) => item.type === 'text' && typeof item.text === 'string')
    .map((item) => item.text ?? '')
    .join('\n');
}

/**
 * A validated, executable browser MCP tool call. Delegates execution to the
 * {@link BrowserManager} and normalizes the result into a {@link ToolResult}.
 */
class BrowserMcpToolInvocation extends BaseToolInvocation<
  ToolParams,
  ToolResult
> {
  constructor(
    params: ToolParams,
    messageBus: MessageBus,
    private readonly browserManager: BrowserManager,
    private readonly mcpToolName: string,
    private readonly toolDescription: string,
    private readonly toolParameterSchema: unknown,
    private readonly transformParams:
      | ((params: ToolParams) => Record<string, unknown>)
      | undefined,
    _toolName?: string,
    _toolDisplayName?: string,
  ) {
    super(
      params,
      messageBus,
      _toolName,
      _toolDisplayName,
      BROWSER_MCP_SERVER_NAME,
    );
  }

  getDescription(): string {
    return safeJsonStringify(this.params);
  }

  protected override getPolicyUpdateOptions(
    _outcome: ToolConfirmationOutcome,
  ): PolicyUpdateOptions | undefined {
    return { mcpName: BROWSER_MCP_SERVER_NAME };
  }

  protected override async getConfirmationDetails(
    _abortSignal: AbortSignal,
  ): Promise<ToolCallConfirmationDetails | false> {
    const confirmationDetails: ToolMcpConfirmationDetails = {
      type: 'mcp',
      title: 'Confirm Browser Tool Execution',
      serverName: BROWSER_MCP_SERVER_NAME,
      toolName: this._toolName ?? this.mcpToolName,
      toolDisplayName: this._toolDisplayName ?? this._toolName ?? this.mcpToolName,
      toolArgs: this.params,
      toolDescription: this.toolDescription,
      toolParameterSchema: this.toolParameterSchema,
      onConfirm: async (outcome: ToolConfirmationOutcome) => {
        await this.publishPolicyUpdate(outcome);
      },
    };
    return confirmationDetails;
  }

  async execute(signal: AbortSignal): Promise<ToolResult> {
    const callArgs = this.transformParams
      ? this.transformParams(this.params)
      : this.params;

    let result: McpToolCallResult;
    try {
      result = await this.browserManager.callTool(
        this.mcpToolName,
        callArgs,
        signal,
      );
    } catch (error) {
      const errorMsg = error instanceof Error ? error.message : String(error);
      return {
        llmContent: `Error: ${errorMsg}`,
        returnDisplay: errorMsg,
        error: { message: errorMsg },
      };
    }

    const textContent = extractTextContent(result.content);

    if (result.isError) {
      return {
        llmContent: `Error: ${textContent}`,
        returnDisplay: textContent || 'Browser tool reported an error.',
        error: { message: textContent },
      };
    }

    return {
      llmContent: textContent,
      returnDisplay: textContent,
      error: undefined,
    };
  }
}

/**
 * A declarative tool that wraps a single browser MCP tool (or a composite
 * helper) and routes execution through the {@link BrowserManager}.
 */
class BrowserMcpTool extends BaseDeclarativeTool<ToolParams, ToolResult> {
  constructor(
    private readonly browserManager: BrowserManager,
    messageBus: MessageBus,
    name: string,
    description: string,
    parameterSchema: unknown,
    private readonly mcpToolName: string,
    private readonly transformParams?: (
      params: ToolParams,
    ) => Record<string, unknown>,
  ) {
    super(
      name,
      name,
      description,
      Kind.Other,
      parameterSchema,
      messageBus,
      /* isOutputMarkdown */ true,
      /* canUpdateOutput */ false,
    );
  }

  protected createInvocation(
    params: ToolParams,
    messageBus: MessageBus,
    _toolName?: string,
    _toolDisplayName?: string,
  ): ToolInvocation<ToolParams, ToolResult> {
    return new BrowserMcpToolInvocation(
      params,
      messageBus,
      this.browserManager,
      this.mcpToolName,
      this.description,
      this.parameterSchema,
      this.transformParams,
      _toolName,
      _toolDisplayName,
    );
  }
}

/**
 * The JSON schema for the composite `type_text` tool.
 */
const TYPE_TEXT_SCHEMA = {
  type: 'object',
  properties: {
    uid: {
      type: 'string',
      description:
        'The uid of the target input element, taken from a page snapshot.',
    },
    text: {
      type: 'string',
      description: 'The text to type into the element.',
    },
    submit: {
      type: 'boolean',
      description: 'Whether to submit the form (press Enter) after typing.',
    },
  },
  required: ['uid', 'text'],
} as const;

/**
 * Builds the composite `type_text` tool, which types text into a target element
 * by delegating to the underlying `fill` MCP tool.
 */
function createTypeTextTool(
  browserManager: BrowserManager,
  messageBus: MessageBus,
): BrowserMcpTool {
  return new BrowserMcpTool(
    browserManager,
    messageBus,
    'type_text',
    'Type text into a page element identified by its uid. Optionally submit ' +
      'the form after typing.',
    TYPE_TEXT_SCHEMA,
    'fill',
    (params) => ({
      uid: params['uid'],
      value: params['text'],
      ...(params['submit'] !== undefined ? { submit: params['submit'] } : {}),
    }),
  );
}

/**
 * Creates declarative tools for every discovered browser MCP tool, plus a
 * composite `type_text` tool that is always included.
 */
export async function createMcpDeclarativeTools(
  browserManager: BrowserManager,
  messageBus: MessageBus,
): Promise<AnyDeclarativeTool[]> {
  const discovered = await browserManager.getDiscoveredTools();

  const tools: AnyDeclarativeTool[] = discovered.map(
    (tool) =>
      new BrowserMcpTool(
        browserManager,
        messageBus,
        tool.name,
        tool.description ?? '',
        tool.inputSchema ?? { type: 'object', properties: {} },
        tool.name,
      ),
  );

  tools.push(createTypeTextTool(browserManager, messageBus));

  return tools;
}
