import { randomUUID } from 'node:crypto';
import {
  BaseDeclarativeTool,
  BaseToolInvocation,
  Kind,
  type ToolInvocation,
  type ToolResult,
} from '../../tools/tools.js';
import type { Config } from '../../config/config.js';
import type { MessageBus } from '../../confirmation-bus/message-bus.js';
import { LlmRole } from '../../telemetry/llmRole.js';
import { getResponseText } from '../../utils/partUtils.js';
import type { BrowserManager, McpToolCallResult } from './browserManager.js';

/**
 * The name of the MCP tool used to capture a screenshot of the current page.
 */
const SCREENSHOT_TOOL_NAME = 'take_screenshot';

type ToolParams = { instruction: string };

const ANALYZE_SCREENSHOT_SCHEMA = {
  type: 'object',
  properties: {
    instruction: {
      type: 'string',
      description:
        'What to look for or analyze in the current page screenshot ' +
        '(e.g. "find the coordinates of the login button").',
    },
  },
  required: ['instruction'],
} as const;

/**
 * An executable `analyze_screenshot` invocation. Captures a screenshot of the
 * current page and sends it to a visual model for analysis.
 */
class AnalyzeScreenshotInvocation extends BaseToolInvocation<
  ToolParams,
  ToolResult
> {
  constructor(
    params: ToolParams,
    messageBus: MessageBus,
    private readonly browserManager: BrowserManager,
    private readonly config: Config,
    _toolName?: string,
    _toolDisplayName?: string,
  ) {
    super(params, messageBus, _toolName, _toolDisplayName);
  }

  getDescription(): string {
    return `Analyze screenshot: ${this.params.instruction}`;
  }

  async execute(signal: AbortSignal): Promise<ToolResult> {
    // 1. Capture the screenshot.
    let screenshot: McpToolCallResult;
    try {
      screenshot = await this.browserManager.callTool(
        SCREENSHOT_TOOL_NAME,
        {},
        signal,
      );
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      return this.errorResult(
        `Failed to capture screenshot: ${message}`,
        'Failed to capture screenshot.',
      );
    }

    const image = screenshot.content?.find(
      (item) => item.type === 'image' && typeof item.data === 'string',
    );

    if (!image || !image.data) {
      return this.errorResult(
        'Failed to capture screenshot: no image was returned by the browser.',
        'Failed to capture screenshot.',
      );
    }

    // 2. Send the screenshot to the visual model for analysis.
    const { customConfig } = this.config.getBrowserAgentConfig();
    const visualModel = customConfig.visualModel;

    try {
      const response = await this.config.getContentGenerator().generateContent(
        {
          // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
          model: visualModel!,
          contents: [
            {
              role: 'user',
              parts: [
                { text: this.params.instruction },
                {
                  inlineData: {
                    mimeType: image.mimeType ?? 'image/png',
                    data: image.data,
                  },
                },
              ],
            },
          ],
        },
        `browser-analyze-screenshot-${randomUUID()}`,
        LlmRole.UTILITY_TOOL,
      );

      const parts = response?.candidates?.[0]?.content?.parts;
      if (!parts || parts.length === 0) {
        return this.errorResult(
          'Visual model returned no analysis.',
          'Visual model returned no analysis.',
        );
      }

      const text = getResponseText(response) ?? '';
      return {
        llmContent: `Visual Analysis Result:\n${text}`,
        returnDisplay: text,
        error: undefined,
      };
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      if (/404|403|not found|permission/i.test(message)) {
        return this.errorResult(
          `Visual analysis model is not available: ${message}`,
          'Visual analysis model is not available.',
        );
      }
      return this.errorResult(
        `Visual analysis failed: ${message}`,
        'Visual analysis failed.',
      );
    }
  }

  private errorResult(llmContent: string, returnDisplay: string): ToolResult {
    return {
      llmContent,
      returnDisplay,
      error: { message: llmContent },
    };
  }
}

/**
 * A declarative tool that captures a screenshot of the current page and sends
 * it to a visual model for analysis.
 */
class AnalyzeScreenshotTool extends BaseDeclarativeTool<ToolParams, ToolResult> {
  constructor(
    private readonly browserManager: BrowserManager,
    private readonly config: Config,
    messageBus: MessageBus,
  ) {
    super(
      'analyze_screenshot',
      'Analyze Screenshot',
      'Capture a screenshot of the current browser page and analyze it with a ' +
        'visual model. Useful for locating elements visually or reading content ' +
        'that is not present in the accessibility snapshot.',
      Kind.Read,
      ANALYZE_SCREENSHOT_SCHEMA,
      messageBus,
      /* isOutputMarkdown */ true,
      /* canUpdateOutput */ false,
    );
  }

  protected createInvocation(
    params: ToolParams,
    messageBus: MessageBus,
    _toolName?: string,
    _toolDisplayName?: string,
  ): ToolInvocation<ToolParams, ToolResult> {
    return new AnalyzeScreenshotInvocation(
      params,
      messageBus,
      this.browserManager,
      this.config,
      _toolName,
      _toolDisplayName,
    );
  }
}

/**
 * Creates the `analyze_screenshot` declarative tool.
 */
export function createAnalyzeScreenshotTool(
  browserManager: BrowserManager,
  config: Config,
  messageBus: MessageBus,
): AnalyzeScreenshotTool {
  return new AnalyzeScreenshotTool(browserManager, config, messageBus);
}
