import { z } from 'zod';
import type { Config } from '../../config/config.js';
import type { MessageBus } from '../../confirmation-bus/message-bus.js';
import { DEFAULT_GEMINI_MODEL } from '../../config/models.js';
import type { AnyDeclarativeTool } from '../../tools/tools.js';
import type { LocalAgentDefinition } from '../types.js';
import { BROWSER_AGENT_NAME, buildBrowserSystemPrompt } from './browserAgentDefinition.js';
import { BrowserManager } from './browserManager.js';
import { createMcpDeclarativeTools } from './mcpToolWrapper.js';
import { createAnalyzeScreenshotTool } from './analyzeScreenshot.js';

const BrowserResultSchema = z.string();

/**
 * Creates the browser agent definition along with the {@link BrowserManager}
 * that backs its tools.
 *
 * The browser connection is established eagerly (via `ensureConnection`) so that
 * MCP tools can be discovered and wrapped. When a visual model is configured,
 * the `analyze_screenshot` tool and vision-specific prompt guidance are included.
 */
export async function createBrowserAgentDefinition(
  config: Config,
  messageBus: MessageBus,
  printOutput?: (msg: string) => void,
): Promise<{ definition: LocalAgentDefinition; browserManager: BrowserManager }> {
  const { model, customConfig } = config.getBrowserAgentConfig();
  const visionEnabled = !!customConfig.visualModel;

  const browserManager = new BrowserManager(config);
  await browserManager.ensureConnection();

  printOutput?.('Browser agent connected. Discovering browser tools...');

  const tools: AnyDeclarativeTool[] = await createMcpDeclarativeTools(
    browserManager,
    messageBus,
  );

  if (visionEnabled) {
    tools.push(createAnalyzeScreenshotTool(browserManager, config, messageBus));
  }

  const definition: LocalAgentDefinition<typeof BrowserResultSchema> = {
    name: BROWSER_AGENT_NAME,
    kind: 'local',
    displayName: 'Browser Agent',
    description:
      'Autonomously drives a real web browser to accomplish tasks such as ' +
      'navigating sites, filling forms, and extracting information.',
    inputConfig: {
      inputSchema: {
        type: 'object',
        properties: {
          task: {
            type: 'string',
            description:
              'The task to accomplish in the browser, described in natural ' +
              'language.',
          },
        },
        required: ['task'],
      },
    },
    outputConfig: {
      outputName: 'result',
      description:
        'A summary of what was accomplished in the browser, including any ' +
        'requested information or the reason the task could not be completed.',
      schema: BrowserResultSchema,
    },
    modelConfig: {
      model: model ?? DEFAULT_GEMINI_MODEL,
    },
    runConfig: {
      maxTimeMinutes: 10,
      maxTurns: 30,
    },
    toolConfig: {
      tools,
    },
    promptConfig: {
      systemPrompt: buildBrowserSystemPrompt(visionEnabled),
      query:
        'Your task is to accomplish the following in the browser:\n' +
        '<task>\n${task}\n</task>',
    },
  };

  return { definition, browserManager };
}

/**
 * Cleans up the browser agent by closing its {@link BrowserManager}. Resolves to
 * `undefined` even if closing the underlying connection throws.
 */
export async function cleanupBrowserAgent(
  browserManager: BrowserManager,
): Promise<void> {
  try {
    await browserManager.close();
  } catch {
    // Cleanup is best-effort; ignore failures so shutdown always succeeds.
  }
}
