import { BaseToolInvocation, type ToolResult } from '../../tools/tools.js';
import { ToolErrorType } from '../../tools/tool-error.js';
import type { Config } from '../../config/config.js';
import type { MessageBus } from '../../confirmation-bus/message-bus.js';
import type { AnsiOutput } from '../../utils/terminalSerializer.js';
import { LocalAgentExecutor } from '../local-executor.js';
import type { AgentInputs, SubagentActivityEvent } from '../types.js';
import { BROWSER_AGENT_NAME } from './browserAgentDefinition.js';
import {
  cleanupBrowserAgent,
  createBrowserAgentDefinition,
} from './browserAgentFactory.js';

const DESCRIPTION_MAX_LENGTH = 200;

/**
 * A validated, executable invocation of the browser agent.
 *
 * Unlike a plain subagent, the browser agent requires asynchronous setup (to
 * launch/attach the browser and discover its MCP tools) before execution and
 * cleanup (to close the browser) afterwards. This invocation owns that lifecycle.
 */
export class BrowserAgentInvocation extends BaseToolInvocation<
  AgentInputs,
  ToolResult
> {
  constructor(
    private readonly config: Config,
    params: AgentInputs,
    messageBus: MessageBus,
    toolName?: string,
    toolDisplayName?: string,
  ) {
    super(
      params,
      messageBus,
      toolName ?? BROWSER_AGENT_NAME,
      toolDisplayName,
    );
  }

  getDescription(): string {
    const keys = Object.keys(this.params).join(', ');
    const description = `Running browser agent with inputs: ${keys}`;
    return description.slice(0, DESCRIPTION_MAX_LENGTH);
  }

  override toolLocations() {
    return [];
  }

  async execute(
    signal: AbortSignal,
    updateOutput?: (output: string | AnsiOutput) => void,
  ): Promise<ToolResult> {
    let browserManager;
    try {
      const created = await createBrowserAgentDefinition(
        this.config,
        this.messageBus,
        updateOutput ? (msg: string) => updateOutput(msg) : undefined,
      );
      browserManager = created.browserManager;

      const onActivity = (activity: SubagentActivityEvent): void => {
        if (!updateOutput) return;
        if (
          activity.type === 'THOUGHT_CHUNK' &&
          typeof activity.data['text'] === 'string'
        ) {
          updateOutput(`🤖💭 ${activity.data['text']}`);
        }
      };

      const executor = await LocalAgentExecutor.create(
        created.definition,
        this.config,
        onActivity,
      );

      const output = await executor.run(this.params, signal);

      const resultContent = `Browser agent finished.
Termination Reason: ${output.terminate_reason}
Result:
${output.result}`;

      return {
        llmContent: [{ text: resultContent }],
        returnDisplay: resultContent,
      };
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : String(error);
      return {
        llmContent: `Browser agent failed. Error: ${errorMessage}`,
        returnDisplay: `Browser Agent Failed\nError: ${errorMessage}`,
        error: {
          message: errorMessage,
          type: ToolErrorType.EXECUTION_FAILED,
        },
      };
    } finally {
      if (browserManager) {
        await cleanupBrowserAgent(browserManager);
      }
    }
  }
}
