    const client = await this.getRawMcpClient();
    const response = await client.listTools();
    this.discoveredTools = response.tools ?? [];
    return this.discoveredTools;
  }

  /**
   * Calls an MCP tool and normalizes the raw SDK response into a stable shape.
   */
  async callTool(
    toolName: string,
    args: Record<string, unknown>,
    signal?: AbortSignal,
  ): Promise<McpToolCallResult> {
    const client = await this.getRawMcpClient();
    const raw = (await client.callTool(
      { name: toolName, arguments: args },
      undefined,
      signal ? { signal } : undefined,
      // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
    )) as { content?: unknown; isError?: unknown };

    const content = Array.isArray(raw?.content)
      ? // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
        (raw.content as McpContentItem[])
      : [];

    return {
      content,
      isError: raw?.isError === true,
    };
  }

  /**
   * Closes the MCP client connection and releases the underlying transport.
   */
  async close(): Promise<void> {
    const client = this.client;
    const transport = this.transport;
    this.client = undefined;
    this.transport = undefined;
    this.discoveredTools = undefined;

    if (transport) {
      await transport.close();
    }
    if (client) {
      await client.close();
    }
  }

  /**
   * Builds the `npx` arguments used to launch the chrome-devtools-mcp server.
   */
  private buildServerArgs(customConfig: BrowserAgentCustomConfig): string[] {
    const sessionMode = customConfig.sessionMode ?? 'persistent';
    const args: string[] = [
      '-y',
      `chrome-devtools-mcp@${CHROME_DEVTOOLS_MCP_VERSION}`,
      '--experimental-vision',
    ];

    if (customConfig.headless) {
      args.push('--headless');
    }

    if (sessionMode === 'existing') {
      // Attach to an already-running Chrome via the DevTools protocol.
      args.push('--autoConnect');
    } else if (sessionMode === 'isolated') {
      // Launch a throwaway Chrome instance with a temporary profile.
      args.push('--isolated');
      if (customConfig.profilePath) {
        args.push('--userDataDir', customConfig.profilePath);
      }
    } else {
      // Persistent mode (default): reuse a dedicated CLI-owned profile.
      const profileDir =
        customConfig.profilePath ?? this.getDefaultProfilePath();
      args.push('--userDataDir', profileDir);
    }

    return args;
  }

  /**
   * Returns the default persistent profile directory path, which always ends in
   * {@link CLI_BROWSER_PROFILE_DIR}.
   */
  private getDefaultProfilePath(): string {
    return path.join(os.homedir(), '.gemini', CLI_BROWSER_PROFILE_DIR);
  }

