          'Visual analysis model is not available.',
        );
      }
      return this.errorResult(
        `Visual analysis failed: ${message}`,
        'Visual analysis failed.',
      );
    }
  }

  private errorResult(llmContent: string, returnDisplay: string): ToolResult {
